 const list=[...Store.state.professional].sort((a,b)=>(b.date||'').localeCompare(a.date||'')),done=list.filter(x=>x.status==='done').length,withImpact=list.filter(x=>x.pre!==''&&x.post!==''),avg=withImpact.length?withImpact.reduce((n,x)=>n+num(x.post)-num(x.pre),0)/withImpact.length:0;
